// Shared mock data for FreshFinds — single source of truth for all API routes.
// This avoids duplicating vendor/listing data across /api/vendors, /api/listings, /api/search.

const NOW = Date.now();
function minsAgo(m: number) { return new Date(NOW - m * 60000).toISOString(); }
function hoursAgo(h: number) { return new Date(NOW - h * 3600000).toISOString(); }
function daysAgo(d: number) { return new Date(NOW - d * 86400000).toISOString(); }
function pickupToday(hour: number): string {
  const d = new Date();
  d.setHours(hour, 0, 0, 0);
  return d.toISOString();
}
export function expireAfter(postedAtIso: string): string {
  return new Date(new Date(postedAtIso).getTime() + 24 * 3600000).toISOString();
}
export function parseDietaryTags(tags: string | null): string[] {
  if (!tags) return [];
  try { return JSON.parse(tags); } catch { return []; }
}

