export function getCityBySlug(slug: string): CityDef | undefined {
  return CITIES.find((c) => c.slug === slug.toLowerCase());
}

export function getCityByName(name: string): CityDef | undefined {
  return CITIES.find((c) => c.name.toLowerCase() === name.toLowerCase());
}

export function getCityByState(state: string): CityDef[] {
  return CITIES.filter((c) => c.state === state.toUpperCase());
}

export function getCitiesGroupedByState(): { state: string; stateName: string; cities: CityDef[] }[] {
  const map = new Map<string, { state: string; stateName: string; cities: CityDef[] }>();
  for (const c of CITIES) {
    if (!map.has(c.state)) {
      map.set(c.state, { state: c.state, stateName: c.stateName, cities: [] });
    }
    map.get(c.state)!.cities.push(c);
  }
  return Array.from(map.values());
}

